def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    rows = [i for i, row in enumerate(grid) if len(set(row)) == 1]
    cols = [j for j in range(w) if len({grid[i][j] for i in range(h)}) == 1]
    for i in rows:
        out[i] = [2] * w
    for j in cols:
        for i in range(h):
            out[i][j] = 2
    return out
